class Warehouse {

    /*
    The class manages inventory and orders, including adding products, updating product quantities, retrieving product quantities, creating orders, changing order statuses, and tracking orders.
    */

    let inventory: HashMap<Int64, Product>
    let orders: HashMap<Int64, Order>

    public init() {
        /*
        Initialize two fields.
        this.inventory is a dict that stores the products.
        this.inventory = {Product ID: Product}
        this.orders is a dict that stores the products in a order.
        this.orders = {Order ID: Order}
        */
        this.inventory = HashMap<Int64, Product>()  // Product ID: Product
        this.orders = HashMap<Int64, Order>()  // Order ID: Order
    }

    public func add_product(product_id: Int64, name: String, quantity: Int64): Unit {
        /*
        Add product to inventory and plus the quantity if it has existed in inventory.
        Or just add new product to dict otherwise.
        :param product_id: Int64
        :param name: String, product name
        :param quantity: Int64, product quantity
        >>> warehouse.add_product(1, "product1", 3)
        >>> warehouse.inventory
        {1: Product('product1', 3)}
        */
        if (this.inventory.contains(product_id)) {
            let existingProduct = this.inventory.get(product_id).getOrThrow()
            existingProduct.quantity += quantity
        } else {
            let newProduct = Product(name, quantity)
            this.inventory.add(product_id, newProduct)
        }
    }

    public func update_product_quantity(product_id: Int64, quantity: Int64): Unit {
        /*
        According to product_id, add the quantity to the corresponding product in inventory.
        >>> warehouse.add_product(1, "product1", 3)
        >>> warehouse.update_product_quantity(1, -1)
        >>> warehouse.inventory
        {1: Product('product1', 2)}
        */
        if (this.inventory.contains(product_id)) {
            let product = this.inventory.get(product_id).getOrThrow()
            product.quantity += quantity
        }
    }

    public func get_product_quantity(product_id: Int64): Option<Int64> {
        /*
        Get the quantity of specific product by product_id.
        :param product_id, Int64
        :return: if the product_id is in inventory then return the corresponding quantity,
                or None otherwise.
        >>> warehouse.add_product(1, "product1", 3)
        >>> warehouse.get_product_quantity(1)
        3
        >>> warehouse.get_product_quantity(2)
        None
        */
        if (this.inventory.contains(product_id)) {
            let product = this.inventory.get(product_id).getOrThrow()
            return Some(product.quantity)
        } else {
            return None
        }
    }

    public func create_order(order_id: Int64, product_id: Int64, quantity: Int64): Bool {
        /*
        Create a order which includes the infomation of product, like id and quantity.
        And put the new order into this.orders.
        The default value of status is 'Shipped'.
        :param order_id: Int64
        :param product_id: Int64
        :param quantity: the quantity of product that be selected.
        :return false: only if product_id is not in inventory or the quantity is not adequate
        >>> warehouse.add_product(1, "product1", 3)
        >>> warehouse.create_order(1, 1, 2)
        >>> warehouse.orders
        {1: Order(1, 2, 'Shipped')}
        >>> warehouse.create_order(1, 2, 2)
        false
        */
        if (this.inventory.contains(product_id)) {
            let product = this.inventory.get(product_id).getOrThrow()
            if (product.quantity >= quantity) {
                product.quantity -= quantity
                let newOrder = Order(product_id, quantity, "Shipped")
                this.orders.add(order_id, newOrder)
                return true
            } else {
                return false
            }
        } else {
            return false
        }
    }

    public func change_order_status(order_id: Int64, status: String): Bool {
        /*
        Change the status of order if the input order_id is in this.orders.
        :param order_id: Int64
        :param status: String, the state that is going to change to
        :return false: only if the order_id is not in this.orders
        >>> warehouse.add_product(1, "product1", 3)
        >>> warehouse.create_order(1, 1, 2)
        >>> warehouse.change_order_status(1, "done")
        >>> warehouse.orders
        {1: Order(1, 2, 'done')}
        */
        if (this.orders.contains(order_id)) {
            let order = this.orders.get(order_id).getOrThrow()
            order.status = status
            return true
        } else {
            return false
        }
    }

    public func track_order(order_id: Int64): Option<String> {
        /*
        Get the status of specific order.
        :param order_id: Int64
        :return None: only if the order_id is not in this.orders.
        >>> warehouse.add_product(1, "product1", 3)
        >>> warehouse.create_order(1, 1, 2)
        >>> warehouse.track_order(1)
        'Shipped'
        */
        if (this.orders.contains(order_id)) {
            let order = this.orders.get(order_id).getOrThrow()
            return Some(order.status)
        } else {
            return None
        }
    }
}

import std.collection.HashMap
import std.math.abs

class Weather {

    let weather: String
    let temperature: Float64
    let temperature_units: String

    public init(weather: String, temperature: Float64, temperature_units: String) {
        this.weather = weather
        this.temperature = temperature
        this.temperature_units = temperature_units
    }
}

class WeatherSystem {

    /*
    This is a class representing a weather system that provides functionality to query weather information for a specific city and convert temperature units between Celsius and Fahrenheit.
    */

    var temperature: Float64
    var weather: String
    var city: String
    var weather_list: HashMap<String, Weather>

    public init(city: String) {
        /*
        Initialize the weather system with a city name.
        */
        this.temperature = Float64.NaN
        this.weather = ""
        this.city = city
        this.weather_list = HashMap<String, Weather>()
    }

    public func query(weather_list: HashMap<String, Weather>, tmp_units!: String = 'celsius'): Option<(Float64, String)> {
        /*
        Query the weather system for the weather and temperature of the city,and convert the temperature units based on the input parameter.
        :param weather_list: a dictionary of weather information for different cities,HashMap<String, Weather>.
        :param tmp_units: the temperature units to convert to, String.
        :return: the temperature and weather of the city, Option<Float64, String>.
        >>> weatherSystem = WeatherSystem('New York')
        >>> weather_list = HashMap<String, Weather>()
        >>> weather_list['New York'] = Weather('sunny', 27.0, 'celsius')
        >>> weather_list['Beijing'] = Weather('cloudy', 23.0, 'celsius')
        >>> weatherSystem.query(weather_list)
        (27.0, 'sunny')

        */
        match (weather_list.get(this.city)) {
            case Some(weather_data) =>
                this.weather = weather_data.weather
                this.temperature = weather_data.temperature

                // Convert temperature if needed
                if (tmp_units == 'fahrenheit' && weather_data.temperature_units == 'celsius') {
                    this.temperature = this.celsius_to_fahrenheit()
                } else if (tmp_units == 'celsius' && weather_data.temperature_units == 'fahrenheit') {
                    this.temperature = this.fahrenheit_to_celsius()
                }

                return Some((this.temperature, this.weather))
            case None =>
                return None
        }
    }

    public func set_city(city: String): Unit {
        /*
        Set the city of the weather system.
        :param city: the city to set, String.
        :return: Unit
        >>> weatherSystem = WeatherSystem('New York')
        >>> weatherSystem.set_city('Beijing')
        >>> weatherSystem.city
        'Beijing'

        */
        this.city = city
    }

    public func celsius_to_fahrenheit(): Float64 {
        /*
        Convert the temperature from Celsius to Fahrenheit.
        :return: the temperature in Fahrenheit, Float64.
        >>> weatherSystem = WeatherSystem('New York')
        >>> weatherSystem.temperature = 27.0
        >>> weatherSystem.celsius_to_fahrenheit()
        80.6

        */
        return this.temperature * 9.0 / 5.0 + 32.0
    }

    public func fahrenheit_to_celsius(): Float64 {
        /*
        Convert the temperature from Fahrenheit to Celsius.
        :return: the temperature in Celsius, Float64.
        >>> weatherSystem = WeatherSystem('New York')
        >>> weatherSystem.temperature = 80.6
        >>> weatherSystem.fahrenheit_to_celsius()
        26.999999999999996

        */
        return (this.temperature - 32.0) * 5.0 / 9.0
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class Words2Numbers {

    /*
    The class provides a text-to-number conversion utility, allowing conversion of written numbers (in words) to their numerical representation.
    */

    let numwords: HashMap<String, (Int64, Int64)>
    let units: ArrayList<String>
    let tens: ArrayList<String>
    let scales: ArrayList<String>
    let ordinal_words: HashMap<String, Int64>
    let ordinal_endings: ArrayList<(String, String)>

    public init() {
        /*
        Initialize the word lists and dictionaries required for conversion
        */
        this.numwords = HashMap<String, (Int64, Int64)>()
        this.units = ArrayList<String>(["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"])
        this.tens = ArrayList<String>(["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"])
        this.scales = ArrayList<String>(["hundred", "thousand", "million", "billion", "trillion"])

        this.numwords["and"] = (1, 0)
        for (idx in 0..this.units.size) {
            this.numwords[this.units[idx]] = (1, idx)
        }
        for (idx in 0..this.tens.size) {
            this.numwords[this.tens[idx]] = (1, idx * 10)
        }
        for (idx in 0..this.scales.size) {
            if (idx * 3 == 0) {
                this.numwords[this.scales[idx]] = (10 ** 2, 0)
            } else {
                this.numwords[this.scales[idx]] = (Int64(10.0 ** (idx * 3)), 0)
            }
        }

        this.ordinal_words = HashMap<String, Int64>([('first', 1), ('second', 2), ('third', 3), ('fifth', 5), ('eighth', 8), ('ninth', 9), ('twelfth', 12)])
        this.ordinal_endings = ArrayList<(String, String)>([('ieth', 'y'), ('th', '')])
    }

    public func text2int(textnum: String): String {
        /*
        Convert the word string to the corresponding integer string
        :param textnum: String, the word string to be converted
        :return: String, the final converted integer string
        >>> w2n = Words2Numbers()
        >>> w2n.text2int("thirty-two")
        "32"
        */
        if (!this.is_valid_input(textnum)) {
            return "0"
        }

        let words = textnum.split(" ")
        var current = 0
        var result = 0

        for (word in words) {
            let wordLower = word.toLowerCase()

            if (this.numwords.contains(wordLower)) {
                let (scale, increment) = this.numwords.get(wordLower).getOrThrow()
                current = current * scale + increment
                if (scale > 100) {
                    result += current
                    current = 0
                }
            } else if (wordLower.contains("-")) {
                let parts = wordLower.split("-")
                var partValue = 0
                for (part in parts) {
                    if (this.numwords.contains(part)) {
                        let (scale, increment) = this.numwords.get(part).getOrThrow()
                        if (scale == 1 && increment >= 20) {
                            partValue += increment
                        } else if (scale == 1 && increment < 20) {
                            partValue += increment
                        }
                    }
                }
                current += partValue
            }
        }

        return (result + current).toString()
    }

    public func is_valid_input(textnum: String): Bool {
        /*
        Check if the input text contains only valid words that can be converted into numbers.
        :param textnum: The input text containing words representing numbers.
        :return: true if input is valid, false otherwise.
        >>> w2n = Words2Numbers()
        >>> w2n.is_valid_input("thirty-two")
        false
        */
        if (textnum.isEmpty()) {
            return false
        }

        let words = textnum.split(" ")
        var hasValidNumber = false

        for (word in words) {
            let wordLower = word.toLowerCase()
            var isValidWord = false

            if (this.numwords.contains(wordLower)) {
                isValidWord = true
                hasValidNumber = true
            } else if (wordLower.contains("-")) {
                let parts = wordLower.split("-")
                var allPartsValid = true
                for (part in parts) {
                    if (!this.numwords.contains(part)) {
                        allPartsValid = false
                        break
                    }
                }
                if (allPartsValid) {
                    isValidWord = true
                    hasValidNumber = true
                }
            }

            if (!isValidWord) {
                return false
            }
        }

        return hasValidNumber
    }
}
